    def read_ints():
        return map(int, sys.stdin.readline().split())

    n, m = read_ints()
    enemies = [tuple(read_ints()) for _ in range(m)]

    # Create adjacency list for the graph
    graph = [[] for _ in range(n)]
    for a, b in enemies:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    # Try to color the graph using two colors
    color = [-1] * n

    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if color[neighbor] == -1:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

    # Check if the graph is bipartite
    for i in range(n):
        if color[i] == -1:
            if not dfs(i, 0):
                print(-1)
                return

    # Convert the coloring to the required output format
    result = ''.join('0' if c == 0 else '1' for c in color)
    print(result)

